function validate([s, k]) {
  if (s.length < 1 || s.length > 100) return 's must have 1 to 100 letters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  if (!Number.isInteger(k) || k < 1 || k > 10) return 'k must be a whole number from 1 to 10.';
  return null;
}

