function getLucky(s, k) {
  // The first transform can be done letter by letter: a position's digits are its tens and its units.
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  let value = 0;
  for (const ch of s) {
    const position = alphabet.indexOf(ch) + 1;
    value += Math.floor(position / 10) + (position % 10);
  }
  for (let round = 1; round < k; round++) {
    let next = 0;
    while (value > 0) {
      next += value % 10;
      value = Math.floor(value / 10);
    }
    value = next;
  }
  return value;
}

