function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const length = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  // Some strings use only a few letters so repeated and high-valued letters show up.
  const span = rand() < 0.3 ? 3 : 26;
  const offset = Math.floor(rand() * (27 - span));
  let s = '';
  for (let i = 0; i < length; i++) s += letters[offset + Math.floor(rand() * span)];
  const k = rand() < 0.5 ? 1 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 10);
  return [s, k];
}
